const pages = $input.all();

if (pages.length === 0) {
  return [{ total: 0, message: 'Keine Daten in dieser Woche.' }];
}

// Duygu dağılımı say
const emotionCount = {};
const scenarioCount = { 'customer-service': 0, 'coaching': 0, 'hr': 0, 'general': 0 };
const alertCount = { 'OK': 0, 'WARNUNG': 0, 'KRITISCH': 0 };
const polarityCount = { 'positiv': 0, 'negativ': 0, 'neutral': 0 };

for (const page of pages) {
  const props = page.json.properties || {};
  const emotion = props['Emotion']?.select?.name || 'Unbekannt';
  const scenario = props['Szenario']?.select?.name || 'general';
  const alertLevel = props['Alert-Level']?.select?.name || 'OK';
  const polarity = props['Polarität']?.select?.name || 'neutral';

  emotionCount[emotion] = (emotionCount[emotion] || 0) + 1;
  scenarioCount[scenario] = (scenarioCount[scenario] || 0) + 1;
  alertCount[alertLevel] = (alertCount[alertLevel] || 0) + 1;
  polarityCount[polarity] = (polarityCount[polarity] || 0) + 1;
}

const total = pages.length;
const topEmotion = Object.entries(emotionCount).sort((a,b)=>b[1]-a[1])[0]?.[0] || 'N/A';
const alertRate = Math.round(((alertCount['WARNUNG']||0) + (alertCount['KRITISCH']||0)) / total * 100);
const positiveRate = Math.round((polarityCount['positiv']||0) / total * 100);

// Duygu listesi sıralı
const emotionList = Object.entries(emotionCount)
  .sort((a,b)=>b[1]-a[1])
  .map(([e,c]) => `${e}: ${c}x (${Math.round(c/total*100)}%)`)
  .join('\n');

// Haftanın başı ve sonu
const now = new Date();
const weekStart = new Date(now);
weekStart.setDate(now.getDate() - 7);

return [{
  total,
  topEmotion,
  alertRate,
  positiveRate,
  emotionCount,
  emotionList,
  scenarioCount,
  alertCount,
  polarityCount,
  weekStart: weekStart.toLocaleDateString('de-DE'),
  weekEnd: now.toLocaleDateString('de-DE'),
  trend: positiveRate >= 60 ? '📈 Positiv' : positiveRate >= 40 ? '➡️ Neutral' : '📉 Negativ'
}];

